import sys

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    by_left = [[] for _ in range(n + 1)]
    p = 2
    for _ in range(m):
        l, r, x = data[p], data[p + 1], data[p + 2]
        p += 3
        by_left[l].append((r, x))

    # threshold[l][x] is the minimum R of a condition with
    # L >= l and X = x (or n+1 if there is no such condition).
    inf = n + 1
    threshold = [[inf] * (n + 2) for _ in range(n + 2)]
    current = [inf] * (n + 2)
    for l in range(n, 0, -1):
        for r, x in by_left[l]:
            if r < current[x]:
                current[x] = r
        threshold[l] = current.copy()

    comb = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        comb[i][0] = comb[i][i] = 1
        for j in range(1, i):
            comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD

    dp = [[0] * (n + 2) for _ in range(n + 2)]
    for i in range(1, n + 2):
        dp[i][i - 1] = 1

    for length in range(1, n + 1):
        for l in range(1, n - length + 2):
            r = l + length - 1
            total = 0
            row = threshold[l]
            for k in range(l, r + 1):
                if row[k] > r:
                    total += dp[l][k - 1] * dp[k + 1][r] * comb[length - 1][k - l]
            dp[l][r] = total % MOD

    print(dp[1][n])

if __name__ == '__main__':
    main()

