def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    a = data[1:]
    vmax = max(a)

    phi = list(range(vmax + 1))
    for p in range(2, vmax + 1):
        if phi[p] == p:
            for x in range(p, vmax + 1, p):
                phi[x] -= phi[x] // p

    divisors = [[] for _ in range(vmax + 1)]
    for d in range(1, vmax + 1):
        for x in range(d, vmax + 1, d):
            divisors[x].append(d)

    weighted = [0] * (vmax + 1)
    weight = 1
    answer = 0
    output = []

    for x in a:
        added = 0
        for d in divisors[x]:
            added += phi[d] * weighted[d]

        # Existing subsequences occur both with and without the new element.
        answer = (2 * answer + added) % MOD
        output.append(str(answer))

        for d in divisors[x]:
            weighted[d] = (weighted[d] + weight) % MOD
        weight = (2 * weight) % MOD

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    main()

