import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    values = data[1:1 + n]
    limit = max(values, default=1)

    spf = list(range(limit + 1))
    if limit >= 1:
        spf[1] = 1
    p = 2
    while p * p <= limit:
        if spf[p] == p:
            for multiple in range(p * p, limit + 1, p):
                if spf[multiple] == multiple:
                    spf[multiple] = p
        p += 1

    xor_sum = 0
    for value in values:
        factors = 0
        while value > 1:
            value //= spf[value]
            factors += 1
        xor_sum ^= factors

    sys.stdout.write("Anna\n" if xor_sum else "Bruno\n")


if __name__ == "__main__":
    main()

