    def maxSubarrays(self,n:int,conflictingPairs:List[List[int]])->int:
        by=[[] for _ in range(n+1)]
        for i,(a,b) in enumerate(conflictingPairs):
            if a>b:a,b=b,a
            by[b].append((a,i))
        m1=m2=0; id1=-1
        gain=[0]*len(conflictingPairs); base=0
        for r in range(1,n+1):
            for l,i in by[r]:
                if l>m1:
                    m2=m1; m1=l; id1=i
                elif l==m1:
                    m2=m1
                elif l>m2:
                    m2=l
            base += r-m1
            if id1>=0: gain[id1]+=m1-m2
        return base+max(gain)

