        ending = [[] for _ in range(n + 1)]
        for idx, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            ending[b].append((a, idx))

        largest = 0
        second = 0
        largest_id = -1
        gains = [0] * len(conflictingPairs)
        total = 0

        for right in range(1, n + 1):
            for left, idx in ending[right]:
                if left > largest:
                    second = largest
                    largest = left
                    largest_id = idx
                elif left == largest:
                    second = largest
                elif left > second:
                    second = left

            total += right - largest
            if largest_id != -1:
                gains[largest_id] += largest - second

        return total + max(gains)

