class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        L = len(s)
        C = [[0]*(L+1) for _ in range(L+1)]
        C[0][0] = 1
        for i in range(1, L+1):
            C[i][0] = C[i][i] = 1
            for j in range(1, i):
                C[i][j] = (C[i-1][j-1] + C[i-1][j]) % MOD
        good = [False]*(L+1)
        for m in range(1, L+1):
            x = m
            steps = 0
            while x != 1:
                x = x.bit_count()
                steps += 1
            good[m] = steps <= k-1
        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                r = L-i-1
                for m in range(1, L+1):
                    if good[m] and m >= ones:
                        q = m-ones
                        if q <= r:
                            ans = (ans + C[r][q]) % MOD
                ones += 1
        return ans

