import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n, m = data[0], data[1]
    rows = [0] * n
    p = 2
    for _ in range(m):
        u, v = data[p] - 1, data[p + 1] - 1
        p += 2
        rows[u] ^= 1 << v
        rows[v] ^= 1 << u

    # Put the adjacency matrix into reduced row echelon form over GF(2).
    a = rows[:]
    pivots = []
    rank = 0
    for col in range(n):
        chosen = -1
        for i in range(rank, n):
            if (a[i] >> col) & 1:
                chosen = i
                break
        if chosen < 0:
            continue
        a[rank], a[chosen] = a[chosen], a[rank]
        for i in range(n):
            if i != rank and ((a[i] >> col) & 1):
                a[i] ^= a[rank]
        pivots.append(col)
        rank += 1

    pivot_set = set(pivots)
    free = [c for c in range(n) if c not in pivot_set]

    # Each free variable set to one gives a nullspace basis vector.
    basis = []
    for f in free:
        vec = 1 << f
        for i, pivot in enumerate(pivots):
            if (a[i] >> f) & 1:
                vec |= 1 << pivot
        basis.append(vec)

    ans = [0] * n
    for bit, vec in enumerate(basis):
        for v in range(n):
            if (vec >> v) & 1:
                ans[v] |= 1 << bit

    if any(x == 0 for x in ans):
        print("No")
    else:
        print("Yes")
        print(*ans)

if __name__ == "__main__":
    main()

