from array import array
class Solution:
 def lenOfVDiagonal(self, grid):
  n=len(grid); m=len(grid[0]); N=n*m
  dirs=((1,1),(1,-1),(-1,-1),(-1,1))
  ss=[]
  for d,(dr,dc) in enumerate(dirs):
   a=array('H',[0])*(2*N)
   rs=range(n-1,-1,-1) if dr==1 else range(n)
   cs=range(m-1,-1,-1) if dc==1 else range(m)
   for r in rs:
    for c in cs:
     x=r*m+c; v=grid[r][c]
     if v==2 or v==0:
      p=0 if v==2 else 1; z=1
      rr=r+dr; cc=c+dc
      if 0<=rr<n and 0<=cc<m:
       y=rr*m+cc
       if a[(1-p)*N+y]: z+=a[(1-p)*N+y]
      a[p*N+x]=z
   ss.append(a)
  ans=0
  for d,(dr,dc) in enumerate(dirs):
   nd=(d+1)%4; ndr,ndc=dirs[nd]
   t=array('H',[0])*(2*N)
   rs=range(n-1,-1,-1) if dr==1 else range(n)
   cs=range(m-1,-1,-1) if dc==1 else range(m)
   for r in rs:
    for c in cs:
     x=r*m+c; v=grid[r][c]
     if v!=2 and v!=0: continue
     p=0 if v==2 else 1; z=1; q=1-p
     rr=r+dr; cc=c+dc
     if 0<=rr<n and 0<=cc<m:
      y=rr*m+cc
      w=t[q*N+y]
      if w: z=max(z,1+w)
     rr=r+ndr; cc=c+ndc
     if 0<=rr<n and 0<=cc<m:
      y=rr*m+cc
      w=ss[nd][q*N+y]
      if w: z=max(z,1+w)
     t[p*N+x]=z
   for r in range(n):
    for c in range(m):
     if grid[r][c]==1:
      rr=r+dr; cc=c+dc
      cur=1
      if 0<=rr<n and 0<=cc<m:
       y=rr*m+cc
       w=t[y] # phase 0 base
       if w: cur+=w
      if cur>ans: ans=cur
  return ans

