from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        CAP = 10**15 + 1
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = min(CAP, fact[i - 1] * i)

        unused = [True] * (n + 1)
        odds = (n + 1) // 2
        evens = n // 2
        result = []
        required = None

        def count_completions(o: int, e: int, parity: int) -> int:
            remaining = o + e
            if remaining == 0:
                return 1
            matching = o if parity == 1 else e
            other = e if parity == 1 else o
            if matching < (remaining + 1) // 2 or other < remaining // 2:
                return 0
            return min(CAP, fact[o] * fact[e])

        for _ in range(n):
