class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        half = (n + 1) // 2

        # Powers are indexed by the position from the right (units = 0).
        p10 = [1] * n
        for i in range(1, n):
            p10[i] = (p10[i - 1] * 10) % k

        coeff = []
        for i in range(half):
            j = n - 1 - i
            if i == j:
                coeff.append(p10[i])
            else:
                coeff.append((p10[i] + p10[j]) % k)

        # shifted[s][mask] shifts every residue represented in mask by s.
        shifted = [[0] * (1 << k) for _ in range(k)]
        for s in range(k):
            for mask in range(1 << k):
                v = 0
                for r in range(k):
                    if mask & (1 << r):
                        v |= 1 << ((r + s) % k)
                shifted[s][mask] = v

        # suffix[i] contains the residues obtainable by positions i onward.
        suffix = [0] * (half + 1)
        suffix[half] = 1
        for i in range(half - 1, -1, -1):
            lo = 1 if i == 0 else 0
            possible = 0
            for d in range(lo, 10):
                possible |= shifted[(d * coeff[i]) % k][suffix[i + 1]]
            suffix[i] = possible

        # Greedily choose the largest feasible digit at each position.
        current = 0
        left = []
        for i in range(half):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-current - d * coeff[i]) % k
                if suffix[i + 1] & (1 << need):
                    left.append(str(d))
                    current = (current + d * coeff[i]) % k
                    break

        return ''.join(left + left[:n // 2][::-1])

