class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        from array import array
        n=len(nums)
        ng=[n]*n; st=[]
        for i,x in enumerate(nums):
            while st and nums[st[-1]] < x:
                ng[st.pop()]=i
            st.append(i)
        ds=[array('i',ng)]
        ss=[array('q',(nums[i]*(ng[i]-i) for i in range(n)))]
        lev=(n.bit_length())
        for z in range(1,lev):
            pd,ps=ds[-1],ss[-1]
            nd=array('i',[n])*n
            ns=array('q',[0])*n
            for i in range(n):
                mid=pd[i]
                ns[i]=ps[i]
                if mid<n:
                    nd[i]=pd[mid]
                    ns[i]+=ps[mid]
            ds.append(nd); ss.append(ns)
        pref=[0]
        for x in nums: pref.append(pref[-1]+x)
        def cost(l,r):
            cur=l; total=0
            for z in range(lev-1,-1,-1):
                d=ds[z][cur]
                if d<=r:
                    total+=ss[z][cur]; cur=d
            total += nums[cur]*(r-cur+1)
            return total-(pref[r+1]-pref[l])
        ans=0
        for r in range(n):
            lo,hi=0,r+1
            while lo<hi:
                m=(lo+hi)//2
                if cost(m,r)<=k: hi=m
                else: lo=m+1
            ans += r-lo+1
        return ans

