class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n=len(parent)
        ch=[[] for _ in range(n)]
        for i in range(1,n): ch[parent[i]].append(i)
        order=[]; sizes=[0]*n
        stack=[(0,0)]
        while stack:
            v,k=stack[-1]
            if k < len(ch[v]):
                stack[-1]=(v,k+1)
                stack.append((ch[v][k],0))
            else:
                stack.pop(); order.append(v)
                sizes[v]=1+sum(sizes[u] for u in ch[v])
        pos=[0]*n
        t=[]
        for j,v in enumerate(order): pos[v]=j; t.append(s[v])
        d1=[0]*n; l=0; r=-1
        for i in range(n):
            k=1 if i>r else min(d1[l+r-i],r-i+1)
            while i-k>=0 and i+k<n and t[i-k]==t[i+k]: k+=1
            d1[i]=k
            if i+k-1>r: l=i-k+1; r=i+k-1
        d2=[0]*n; l=0; r=-1
        for i in range(n):
            k=0 if i>r else min(d2[l+r-i+1],r-i+1)
            while i-k-1>=0 and i+k<n and t[i-k-1]==t[i+k]: k+=1
            d2[i]=k
            if i+k-1>r: l=i-k; r=i+k-1
        ans=[]
        for v in range(n):
            rr=pos[v]; ll=rr-sizes[v]+1; length=sizes[v]
            if length&1: ans.append(d1[(ll+rr)//2]>=length//2+1)
            else: ans.append(d2[(ll+rr+1)//2]>=length//2)
        return ans

