def main():
    n = int(sys.stdin.buffer.read())
    limit = isqrt(n)

    sieve = bytearray(b'\x01') * (limit + 1)
    if limit >= 0:
        sieve[0] = 0
    if limit >= 1:
        sieve[1] = 0
    for p in range(2, isqrt(limit) + 1):
        if sieve[p]:
            start = p * p
            sieve[start:limit + 1:p] = b'\x00' * ((limit - start) // p + 1)

    primes = [x for x in range(2, limit + 1) if sieve[x]]

    eighth_root = isqrt(isqrt(isqrt(n)))
    answer = sum(p <= eighth_root for p in primes)

    j = len(primes) - 1
    for i, p in enumerate(primes):
        if j <= i:
            break
        while j > i and p * primes[j] > limit:
            j -= 1
        if j <= i:
            break
        answer += j - i

    print(answer)

