from typing import List

class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return 0

        # A line for index i is:
        # dp[i] + (x-i)*nums[i] = nums[i]*x + dp[i]-i*nums[i]
        tree = [None] * (4 * n)

        def value(line, x):
            return line[0] * x + line[1]

        def insert(node, left, right, line):
            current = tree[node]
            if current is None:
                tree[node] = line
                return

            mid = (left + right) // 2
            if value(line, mid) > value(current, mid):
                tree[node], line = line, current

            if left == right:
                return

            if value(line, left) > value(tree[node], left):
                insert(node * 2, left, mid, line)
            elif value(line, right) > value(tree[node], right):
                insert(node * 2 + 1, mid + 1, right, line)

        def query(node, left, right, x):
            line = tree[node]
            result = value(line, x) if line is not None else -10**30
            if left == right:
                return result
            mid = (left + right) // 2
            if x <= mid:
