import heapq

class Solution:
    def minOperations(self, n: int, m: int) -> int:
        digits = len(str(n))
        limit = 10 ** digits
        prime = [True] * limit
        prime[0] = False
        if limit > 1:
            prime[1] = False
        for p in range(2, int(limit ** 0.5) + 1):
            if prime[p]:
                for v in range(p * p, limit, p):
                    prime[v] = False
        if prime[n] or prime[m]:
            return -1
        inf = 10 ** 30
        dist = [inf] * limit
        dist[n] = n
        heap = [(n, n)]
        places = [10 ** i for i in range(digits)]
        while heap:
            cost, x = heapq.heappop(heap)
            if cost != dist[x]:
                continue
            if x == m:
                return cost
            for place in places:
                digit = (x // place) % 10
                if digit < 9:
                    y = x + place
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (dist[y], y))
                if digit > 0:
                    y = x - place
                    if not prime[y] and cost + y < dist[y]:
                        dist[y] = cost + y
                        heapq.heappush(heap, (dist[y], y))
        return -1

