from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)

        # Z values: z[i] is the common-prefix length of nums and nums[i:].
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            if i <= right:
                z[i] = min(right - i + 1, z[i - left])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] - 1 > right:
                left, right = i, i + z[i] - 1

        first = [False] * n
        for i in range(1, n):
            first[i] = z[i] >= i

        ans = 0
        # Splits satisfying nums1 being a prefix of nums2.
        for i in range(1, n):
            if first[i] and 2 * i < n:
                ans += n - 2 * i

        # dp[j] is LCP(nums[i:], nums[j:]) for the current i.
        # Processing j increasingly keeps dp[j+1] from the preceding row.
        dp = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            for j in range(i + 1, n):
                if nums[i] == nums[j]:
                    dp[j] = 1 + dp[j + 1]
                else:
                    dp[j] = 0
                length = j - i
                if length <= n - j and dp[j] >= length:
                    # Avoid counting a split already counted by the first rule.
                    if not (first[i] and j >= 2 * i):
                        ans += 1
        return ans

