from typing import List

class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        n = len(source)
        m = len(pattern)
        is_target = [False] * n
        for index in targetIndices:
            is_target[index] = True

        # dp[j] is the minimum number of target characters used by a
        # subsequence matching pattern[:j] among the source seen so far.
        inf = m + 1
        dp = [inf] * (m + 1)
        dp[0] = 0

        for i, ch in enumerate(source):
            cost = 1 if is_target[i] else 0
            for j in range(min(i + 1, m), 0, -1):
                if ch == pattern[j - 1]:
                    candidate = dp[j - 1] + cost
                    if candidate < dp[j]:
                        dp[j] = candidate

        # Every target index not used by the chosen embedding can be removed.
        return len(targetIndices) - dp[m]

